From 464f11dfc19b42796a2775564484af08346f168e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:01:20 +0100
Subject: [PATCH] applets/notifications: open the Trash link in the file
 manager

Clicking "Trash" in a file deletion notification asked to choose an app,
since body links went through Qt.openUrlExternally and no application
handles trash:/. Open them with KIO::OpenUrlJob, like other KDE links.

BUG: 527920
---
 applets/notifications/components/Body.qml    |  4 +++-
 applets/notifications/notificationapplet.cpp | 10 ++++++++++
 applets/notifications/notificationapplet.h   | 11 +++++++++++
 3 files changed, 24 insertions(+), 1 deletion(-)

diff --git a/applets/notifications/components/Body.qml b/applets/notifications/components/Body.qml
index e7a4b85612..a0ed098550 100644
--- a/applets/notifications/components/Body.qml
+++ b/applets/notifications/components/Body.qml
@@ -10,6 +10,8 @@ import QtQuick.Layouts

 import org.kde.kirigami as Kirigami

+import plasma.applet.org.kde.plasma.notifications as Notifications
+
 Kirigami.SelectableLabel {
     id: bodyLabel

@@ -36,7 +38,7 @@ Kirigami.SelectableLabel {
     // Selectable only when we are in desktop mode
     selectByMouse: !Kirigami.Settings.tabletMode

-    onLinkActivated: link => Qt.openUrlExternally(link)
+    onLinkActivated: link => Notifications.UrlOpener.openUrl(link)

     onClicked: modelInterface.bodyClicked()

diff --git a/applets/notifications/notificationapplet.cpp b/applets/notifications/notificationapplet.cpp
index 579dd0d790..fb6011e88e 100644
--- a/applets/notifications/notificationapplet.cpp
+++ b/applets/notifications/notificationapplet.cpp
@@ -12,6 +12,9 @@
 #include <QQuickWindow>
 #include <QScreen>

+#include <KIO/JobUiDelegateFactory>
+#include <KIO/OpenUrlJob>
+
 #include <Plasma/Containment>
 #include <PlasmaQuick/AppletQuickItem>
 #include <PlasmaQuick/Dialog>
@@ -27,6 +30,13 @@ void InputDisabler::makeTransparentForInput(QQuickItem *item)
     }
 }

+void UrlOpener::openUrl(const QUrl &url)
+{
+    auto *job = new KIO::OpenUrlJob(url);
+    job->setUiDelegate(KIO::createDefaultJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled, nullptr));
+    job->start();
+}
+
 NotificationApplet::NotificationApplet(QObject *parent, const KPluginMetaData &data, const QVariantList &args)
     : Plasma::Applet(parent, data, args)
 {
diff --git a/applets/notifications/notificationapplet.h b/applets/notifications/notificationapplet.h
index 0f7cc69433..9c8a2ee372 100644
--- a/applets/notifications/notificationapplet.h
+++ b/applets/notifications/notificationapplet.h
@@ -7,6 +7,7 @@
 #pragma once

 #include <QQuickItem>
+#include <QUrl>
 #include <QWindow>

 #include <Plasma/Applet>
@@ -23,6 +24,16 @@ public:
     Q_INVOKABLE void makeTransparentForInput(QQuickItem *item);
 };

+class UrlOpener : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    QML_SINGLETON
+
+public:
+    Q_INVOKABLE void openUrl(const QUrl &url);
+};
+
 class NotificationApplet : public Plasma::Applet
 {
     Q_OBJECT
-- 
